import gdb

class CounterBreakpoint(gdb.Breakpoint):
    def __init__(self):
        super().__init__("*main", type=gdb.BP_BREAKPOINT)
        self.counter = 0

    def stop(self):
        # Log registers and important memory locations
        regs = ['rax', 'rbx', 'rcx', 'rdx']
        reg_vals = {}
        for reg in regs:
            try:
                val = int(gdb.parse_and_eval(f"${reg}"))
                reg_vals[reg] = val
            except:
                pass

        if 0x1a6 in reg_vals.values() or 0x23 in reg_vals.values() or 0x2d in reg_vals.values():
            print(f"Hit breakpoint {self.counter}:")
            print(f"Register values: {reg_vals}")

        self.counter += 1
        return False

gdb.execute('file /home/ctfplayer/ctf_files/counting')
CounterBreakpoint()
gdb.execute('run')

